import { Group, Mesh, BoxGeometry, PlaneGeometry, Color, DirectionalLight, PointLight } from 'three/webgpu';
import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, length, smoothstep, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const root = new Group();
  root.name = 'home-thumbnail-card';

  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const inkColor = new Color(colors.ink);
  const paperColor = new Color(colors.paper);
  const accentColor = new Color(colors.accent);

  const CARD_W = 1.8;
  const CARD_H = 1.2;
  const CARD_D = 0.09;
  const CAPTION_H = 0.28;

  // ---- Card base plate (machined-metal PBR panel) ----
  const cardGeo = new BoxGeometry(CARD_W, CARD_H, CARD_D);
  const cardMat = new MeshPhysicalNodeMaterial({
    color: inkColor,
    roughness: 0.55,
    metalness: 0.45,
    clearcoat: 0.18,
    clearcoatRoughness: 0.35,
  });
  const cardMesh = new Mesh(cardGeo, cardMat);
  cardMesh.position.set(0, 0, 0);
  root.add(cardMesh);

  // ---- Accent focus edge (hidden until hover/focus) ----
  const edgeGeo = new BoxGeometry(CARD_W + 0.05, CARD_H + 0.05, CARD_D * 0.6);
  const edgeMat = new MeshBasicNodeMaterial({
    color: accentColor,
    transparent: true,
    opacity: 0.0,
  });
  const edgeMesh = new Mesh(edgeGeo, edgeMat);
  edgeMesh.position.set(0, 0, -0.01);
  root.add(edgeMesh);

  // ---- Caption strip (paper strip at bottom, JetBrains Mono territory even w/o copy) ----
  const captionGeo = new BoxGeometry(CARD_W, CAPTION_H, CARD_D * 1.02);
  const captionMat = new MeshPhysicalNodeMaterial({
    color: paperColor,
    roughness: 0.6,
    metalness: 0.05,
    clearcoat: 0.0,
  });
  const captionMesh = new Mesh(captionGeo, captionMat);
  captionMesh.position.set(0, -CARD_H / 2 + CAPTION_H / 2, 0.002);
  root.add(captionMesh);

  // thin accent underline on caption strip (single accent element, <=10% of frame)
  const underlineGeo = new BoxGeometry(CARD_W * 0.28, CAPTION_H * 0.12, CARD_D * 1.05);
  const underlineMat = new MeshPhysicalNodeMaterial({
    color: accentColor,
    roughness: 0.5,
    metalness: 0.3,
  });
  const underlineMesh = new Mesh(underlineGeo, underlineMat);
  underlineMesh.position.set(
    -CARD_W / 2 + CARD_W * 0.14 + 0.06,
    -CARD_H / 2 + CAPTION_H * 0.16,
    0.01
  );
  root.add(underlineMesh);

  // ---- Contact shadow (radial falloff plane, grounded object) ----
  const shadowRadius = CARD_W * 0.75;
  const shadowGeo = new PlaneGeometry(shadowRadius * 2, shadowRadius * 2);
  const shadowOpacityUniform = uniform(0.5);
  const centered = uv().sub(0.5);
  const dist = length(centered).mul(2.0);
  const falloff = smoothstep(1.0, 0.0, dist);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.opacityNode = falloff.mul(shadowOpacityUniform);
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.set(0, -CARD_H / 2 - 0.02, 0.35);
  root.add(shadowMesh);

  // ---- Local lighting: rim/accent, kept within node scope ----
  const rimLight = new DirectionalLight(new Color(colors.accent), 0.7);
  rimLight.position.set(-1.2, 0.8, 1.5);
  root.add(rimLight);

  const fillPoint = new PointLight(new Color(colors.paper), 0.5, 4.0);
  fillPoint.position.set(0.8, 0.6, 1.2);
  root.add(fillPoint);

  // ---- Subject mesh (gear-a.glb) mounted above caption strip ----
  const subjectSlot = new Group();
  const subjectAreaH = CARD_H - CAPTION_H;
  subjectSlot.position.set(0, CAPTION_H / 2, CARD_D / 2 + 0.02);
  root.add(subjectSlot);

  let loadedSubject = null;
  const meshUrl = config?.meshUrl;
  if (meshUrl) {
    ctx.glbLoader.loadGLB(meshUrl).then((gltf) => {
      const scene = gltf.scene ?? gltf.scenes?.[0];
      if (!scene) return;
      loadedSubject = scene;

      const box = new THREE.Box3().setFromObject(scene);
      const size = new THREE.Vector3();
      box.getSize(size);
      const maxDim = Math.max(size.x, size.y, size.z, 0.0001);
      const targetSize = Math.min(CARD_W, subjectAreaH) * 0.62;
      const scaleFactor = targetSize / maxDim;
      scene.scale.setScalar(scaleFactor);

      const center = new THREE.Vector3();
      box.getCenter(center);
      scene.position.sub(center.multiplyScalar(scaleFactor));

      subjectSlot.add(scene);
    }).catch(() => {});
  }

  // ---- Motion: idle weighted breathing (single slow transform) ----
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true });
  idleTl.to(subjectSlot.scale, {
    x: 1.02,
    y: 1.02,
    z: 1.02,
    duration: 2.6,
    ease: 'power1.inOut',
  });

  // ---- Interaction state ----
  let hovering = false;
  let hoverTl = null;
  let pressTl = null;

  const baseY = root.position.y;

  function onHoverStart() {
    if (hovering) return;
    hovering = true;
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(cardMesh.position, { y: 0.15, duration: 0.7, ease: 'power3.out' }, 0);
    hoverTl.to(captionMesh.position, { y: '+=0.15', duration: 0.7, ease: 'power3.out' }, 0);
    hoverTl.to(underlineMesh.position, { y: '+=0.15', duration: 0.7, ease: 'power3.out' }, 0);
    hoverTl.to(subjectSlot.position, { y: '+=0.15', duration: 0.7, ease: 'power3.out' }, 0);
    hoverTl.to(edgeMesh.position, { y: '+=0.15', duration: 0.7, ease: 'power3.out' }, 0);
    hoverTl.to(edgeMat, { opacity: 0.85, duration: 0.3, ease: 'power2.out' }, 0);
  }

  function onHoverEnd() {
    if (!hovering) return;
    hovering = false;
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(cardMesh.position, { y: 0, duration: 0.6, ease: 'power2.out' }, 0);
    hoverTl.to(captionMesh.position, { y: -CARD_H / 2 + CAPTION_H / 2, duration: 0.6, ease: 'power2.out' }, 0);
    hoverTl.to(underlineMesh.position, {
      y: -CARD_H / 2 + CAPTION_H * 0.16,
      duration: 0.6,
      ease: 'power2.out',
    }, 0);
    hoverTl.to(subjectSlot.position, { y: CAPTION_H / 2, duration: 0.6, ease: 'power2.out' }, 0);
    hoverTl.to(edgeMesh.position, { y: 0, duration: 0.6, ease: 'power2.out' }, 0);
    hoverTl.to(edgeMat, { opacity: 0.0, duration: 0.3, ease: 'power2.out' }, 0);
  }

  function onClick() {
    if (pressTl) pressTl.kill();
    pressTl = gsap.timeline();
    pressTl.to(root.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' });
    pressTl.to(root.scale, { x: 1, y: 1, z: 1, duration: 0.35, ease: 'power4.out' });
    ctx.emit('hub-home.select', { nodeId: config?.id ?? 'home-thumbnail-card' });
  }

  root.userData.handlers = {
    onHoverStart,
    onHoverEnd,
    onPointerEnter: onHoverStart,
    onPointerLeave: onHoverEnd,
    onClick,
    onPointerDown: onClick,
  };

  root.userData.cleanup = function cleanup() {
    idleTl.kill();
    if (hoverTl) hoverTl.kill();
    if (pressTl) pressTl.kill();

    [cardGeo, edgeGeo, captionGeo, underlineGeo, shadowGeo].forEach((g) => g.dispose());
    [cardMat, edgeMat, captionMat, underlineMat, shadowMat].forEach((m) => m.dispose());

    if (loadedSubject) {
      loadedSubject.traverse((obj) => {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) {
          const mats = Array.isArray(obj.material) ? obj.material : [obj.material];
          mats.forEach((m) => {
            if (m.map) m.map.dispose();
            m.dispose();
          });
        }
      });
    }

    root.remove(rimLight);
    root.remove(fillPoint);
  };

  return root;
}
